  liveNeighbors: number,
  isCurrentlyAlive: boolean,
): boolean => {
  const isBornOrSurvives = liveNeighbors === NEIGHBORS_FOR_BIRTH;
  const survivesOnTwo =
    liveNeighbors === NEIGHBORS_FOR_SURVIVAL && isCurrentlyAlive;
